# Construct solution via known construction (to avoid recomputing with state). Let's rebuild and extract.
from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

G=50; S=5; K=10; W=6
vpool = IDPool()
def x(w,g,p): return vpool.id(('x',w,g,p))
def z(w,g,p,q): return vpool.id(('z',w,g,p,q))

solver = Glucose4()
for w in range(W):
    for p in range(G):
        lits = [x(w,g,p) for g in range(K)]
        cnf = CardEnc.equals(lits=lits, bound=1, vpool=vpool, encoding=EncType.pairwise)
        for cl in cnf.clauses: solver.add_clause(cl)
for w in range(W):
    for g in range(K):
        lits = [x(w,g,p) for p in range(G)]
        cnf = CardEnc.equals(lits=lits, bound=S, vpool=vpool, encoding=EncType.seqcounter)
        for cl in cnf.clauses: solver.add_clause(cl)
for p in range(G):
    for q in range(p+1,G):
        zlits = []
        for w in range(W):
            for g in range(K):
                zv = z(w,g,p,q)
                solver.add_clause([-zv, x(w,g,p)])
                solver.add_clause([-zv, x(w,g,q)])
                solver.add_clause([-x(w,g,p), -x(w,g,q), zv])
                zlits.append(zv)
        cnf = CardEnc.atmost(lits=zlits, bound=1, vpool=vpool, encoding=EncType.seqcounter)
        for cl in cnf.clauses: solver.add_clause(cl)

# Symmetry breaking: week 0 fixed: golfer p in group p//5
for p in range(G):
    solver.add_clause([x(0, p//5, p)])

res = solver.solve()
print(res)
model = set(solver.get_model())

sched = [0]*300
for w in range(W):
    for p in range(G):
        for g in range(K):
            if x(w,g,p) in model:
                sched[w*50+p]=g
                break

# verify
for w in range(W):
    groups={}
    for p in range(G):
        groups.setdefault(sched[w*50+p],[]).append(p)
    assert len(groups)==10
    for g,ps in groups.items():
        assert len(ps)==5

pair_weeks={}
for w in range(W):
    groups={}
    for p in range(G):
        groups.setdefault(sched[w*50+p],[]).append(p)
    for ps in groups.values():
        for i in range(len(ps)):
            for j in range(i+1,len(ps)):
                pair = (ps[i],ps[j])
                pair_weeks.setdefault(pair,[]).append(w)

for pair, ws in pair_weeks.items():
    assert len(ws)<=1, (pair,ws)
print("OK")
print(sched)
